```tsx
import { useEffect, useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Preview = 'ok' | 'error' | 'empty';

const SAMPLES: Record<
  Preview,
  { orden: string; comis: string; movim: string; mens: string; tone: 'success' | 'error' | 'info' }
> = {
  ok: {
    orden: '0004821',
    comis: '1,234.50',
    movim: '9047215',
    mens: 'PAGO REGISTRADO CORRECTAMENTE',
    tone: 'success',
  },
  error: {
    orden: '0004822',
    comis: '0.00',
    movim: '0',
    mens: 'SALDO INSUFICIENTE PARA EL PAGO',
    tone: 'error',
  },
  empty: {
    orden: '',
    comis: '',
    movim: '',
    mens: '',
    tone: 'info',
  },
};

export default function PagoResultado({ navigate }: { navigate: (to: string) => void }) {
  const [preview, setPreview] = useState<Preview>('ok');
  const data = SAMPLES[preview];

  const nuevoPago = () => navigate('SCR-PAGOORD');
  const menu = () => navigate('SCR-PAGOMEN');

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement | null)?.tagName;
      if (e.key === 'F3') {
        e.preventDefault();
        navigate('SCR-PAGOMEN');
      } else if (e.key === 'Enter' && tag !== 'BUTTON' && tag !== 'SELECT' && tag !== 'INPUT') {
        navigate('SCR-PAGOORD');
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [navigate]);

  const noop = () => {};

  return (
    <Screen
      title="Resultado del pago"
      code="PAGORES"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nuevo pago', onPress: nuevoPago, primary: true },
            { key: 'PF3', label: 'Menú', onPress: menu },
          ]}
        />
      }
    >
      <Stack>
        {preview === 'empty' && (
          <Alert tone="info">
            Todavía no hay un resultado para mostrar. Registre un nuevo pago para ver su resultado.
          </Alert>
        )}

        <Card title="Resultado del pago">
          <Stack>
            <Grid columns={2}>
              <div data-field="RORDEN">
                <TextField
                  label="Orden"
                  hint="Número de orden, 7 dígitos"
                  numeric
                  maxLength={7}
                  value={data.orden}
                  onChange={noop}
                  readOnly
                />
              </div>
              <div data-field="RMOVIM">
                <TextField
                  label="Movimiento"
                  hint="Número de movimiento, hasta 10 dígitos"
                  numeric
                  maxLength={10}
                  value={data.movim}
                  onChange={noop}
                  readOnly
                />
              </div>
              <div data-field="RCOMIS">
                <TextField
                  label="Comisión"
                  hint="Importe con formato ZZZ,ZZ9.99"
                  numeric
                  maxLength={10}
                  value={data.comis}
                  onChange={noop}
                  readOnly
                />
              </div>
            </Grid>

            <div data-field="RMENS">
              <Stack>
                <Row>
                  <strong>Resultado</strong>
                  {preview === 'ok' && <Badge>Aprobado</Badge>}
                  {preview === 'error' && <Badge>Rechazado</Badge>}
                </Row>
                {data.mens ? (
                  <Alert tone={data.tone}>{data.mens}</Alert>
                ) : (
                  <Alert tone="info">Sin resultado</Alert>
                )}
              </Stack>
            </div>
          </Stack>
        </Card>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevoPago}>
            Nuevo pago
          </Button>
          <Button variant="secondary" shortcut="PF3" onClick={menu}>
            Menú
          </Button>
        </Row>

        <Card title="Vista previa del prototipo">
          <SelectField
            label="Estado de ejemplo"
            hint="Solo para la revisión: cambia los datos de muestra mostrados arriba"
            options={[
              { value: 'ok', label: 'Pago registrado' },
              { value: 'error', label: 'Pago rechazado' },
              { value: 'empty', label: 'Sin resultado' },
            ]}
            value={preview}
            onChange={(v: string) => setPreview(v as Preview)}
          />
        </Card>
      </Stack>
    </Screen>
  );
}
